package com.lumen.orders;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class OrderProjectionContractTest {
 @Test void observedPostgresFunctionResultsRemainIdentical(){
  var service=new OrderProjectionService(JdbcFunctions.fromEnvironment());
  for(String tenant:List.of("11","22")){
   var expected=new LinkedHashMap<String,String>();expected.put("tenant_id",tenant);expected.put("order_id","420");expected.put("account_id","7");expected.put("status","PAID");expected.put("amount",tenant.equals("11")?"17.000001":"100.000001");expected.put("accountLabel","ACTIVE");expected.put("releaseLabel",tenant.equals("11")?"STANDARD":"MANUAL_REVIEW");
   assertEquals(expected,service.load(tenant,"420"));
  }
  assertNull(service.load("22","999"));
  System.out.println("bindingLocalScratch="+System.getenv("DT_FUNCTIONS_URL").contains("/dt_test_"));
 }
 @Test void enrichmentPreservesTenantIdentityNullLabelsAndSourceRow(){
  var calls=new ArrayList<String>();var row=new LinkedHashMap<String,String>();row.put("account_id","7");row.put("amount","100.000001");var before=new LinkedHashMap<>(row);
  var functions=new OrderProjectionService.Functions(){
   public Map<String,String> projection(String t,String o){calls.add("projection:"+t+":"+o);return row;}
   public String accountLabel(String t,String a){calls.add("account:"+t+":"+a);return null;}
   public String releaseLabel(String t,String o){calls.add("release:"+t+":"+o);return null;}
  };
  var result=new OrderProjectionService(functions).load("22","9007199254740993");
  assertEquals(List.of("projection:22:9007199254740993","account:22:7","release:22:9007199254740993"),calls);assertEquals(before,row);assertNotSame(row,result);assertEquals("100.000001",result.get("amount"));assertTrue(result.containsKey("accountLabel"));assertNull(result.get("accountLabel"));assertTrue(result.containsKey("releaseLabel"));assertNull(result.get("releaseLabel"));
 }
 @Test void missingProjectionDoesNotCallEnrichment(){
  var functions=new OrderProjectionService.Functions(){public Map<String,String> projection(String t,String o){return null;}public String accountLabel(String t,String a){throw new AssertionError("unexpected account read");}public String releaseLabel(String t,String o){throw new AssertionError("unexpected release read");}};assertNull(new OrderProjectionService(functions).load("22","999"));
 }
}

